import{_ as o}from"./chunks/home-estop.pc.ko.DDxZsvoM.js";import{_ as a}from"./chunks/emo.CGwrrK0y.js";import{_ as c}from"./chunks/home-status.pc.ko.BJCyWPnR.js";import{_ as t,o as d,c as i,a5 as l}from"./chunks/framework.D47SInms.js";const S=JSON.parse('{"title":"비상 정지","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/emergency.md","filePath":"ko/manual/gui/emergency.md","lastUpdated":1791600043000}'),r={name:"ko/manual/gui/emergency.md"};function n(s,e,p,m,g,h){return d(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="비상-정지" tabindex="-1">비상 정지 <a class="header-anchor" href="#비상-정지" aria-label="Permalink to &quot;비상 정지&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>로봇을 움직이는 동안에는 비상 정지 버튼에 언제든 손이 닿도록 해 두십시오. 로봇이 사람이나 물건에 위험이 될 수 있는 상황이면 곧바로 비상 정지 버튼을 누르십시오.</p></div><h2 id="앱의-e-stop" tabindex="-1">앱의 E-STOP <a class="header-anchor" href="#앱의-e-stop" aria-label="Permalink to &quot;앱의 E-STOP&quot;">​</a></h2><p><img src="'+o+'" alt="E-STOP 확인"></p><p>빨간 <code>E-STOP</code> 버튼은 제어 홈에서는 상단 바 오른쪽에 있습니다. 폭이 720 px 미만인 아주 작은 화면에서는 글자 없이 비상 아이콘만 보입니다(휴머노이드는 <code>RL 정지</code> 글자가 남습니다). 다른 화면에서는 로봇이 연결돼 있거나 끊긴 뒤 다시 붙는 동안 헤더 오른쪽에 나옵니다. 끊긴 뒤에도 8초 동안은 눌립니다. 누르면 <code>비상 정지하시겠습니까?</code> 확인 창이 열립니다.</p><blockquote><p>로봇이 즉시 모든 동작을 멈추고 힘을 차단합니다. 제어를 다시 시작하려면 재초기화가 필요합니다.</p></blockquote><p><code>정지</code>를 누르면 비상 정지가 전송되고, <code>취소</code>를 누르면 창이 닫힙니다. 이 확인 없이 E-STOP이 나가는 경로는 없습니다.</p><ul><li>앱은 비상 정지를 대기 중인 명령보다 앞세워 전용 채널로 보내고, 신뢰 명령 채널로 한 번 더 보냅니다.</li><li>로봇 소유권이 없어도 됩니다. 로봇은 연결된 어느 기기의 E-STOP이든 소유권 검사를 건너뛰고 받아들입니다. 소유권을 가져오지는 않으며, 현재 소유자는 그대로 유지됩니다.</li><li>로봇이 명령에 응답하지 않으면 앱 로그에 <code>E-Stop 전송 실패 — 응답 없음. 물리 E-Stop을 사용하세요</code>가 남습니다. 기다리지 말고 물리 버튼을 누르세요.</li></ul><h2 id="물리적-비상-정지-버튼" tabindex="-1">물리적 비상 정지 버튼 <a class="header-anchor" href="#물리적-비상-정지-버튼" aria-label="Permalink to &quot;물리적 비상 정지 버튼&quot;">​</a></h2><figure><img src="'+a+'" alt="로봇 후면의 비상 정지 버튼"><figcaption style="text-align:center;">[ 비상 정지 누름 버튼 — 로봇 후면에 위치 ]</figcaption></figure><p>물리적 <strong>비상 정지 버튼</strong>을 누르거나 앱의 <code>E-STOP</code>을 확정하면:</p><ul><li>모든 관절이 <strong>High Damping</strong> 모드로 전환됩니다.</li><li>로봇은 외부 움직임에 저항하지만 토크나 위치 명령을 <strong>받지 않습니다</strong>.</li><li>자세를 버티지 못하고 제 무게에 바닥으로 내려앉을 수 있습니다.</li></ul><p>High Damping 모드는 사용자와 로봇을 함께 보호합니다. 비상 정지를 풀고 로봇을 재초기화할 때까지는 어떤 동작 명령도 실행하지 않습니다.</p><h2 id="복구" tabindex="-1">복구 <a class="header-anchor" href="#복구" aria-label="Permalink to &quot;복구&quot;">​</a></h2><ol><li><strong>안전 확인</strong> — 로봇 주변 2 m 이내에 사람이나 동물이 없는지 확인합니다.</li><li><strong>버튼 해제</strong> — 물리 버튼을 눌렀다면 시계 방향으로 돌려 잠금을 해제합니다.</li><li><strong>초기 자세로 복귀</strong> — 로봇이 넘어졌거나 자리가 밀렸으면 평평한 바닥에서 <a href="/RBQ/nightly/ko/manual/operation/initial-pose.html">초기 자세</a>로 되돌립니다. High Damping 상태에서 관절을 강제로 움직이지 마세요.</li><li><strong>재초기화</strong> — <a href="/RBQ/nightly/ko/manual/gui/control-home.html">제어 홈</a>에서 자동 기동 시퀀스나 Stand 모션을 실행하고, 상단 바의 로봇 상태를 확인한 뒤 작동을 재개합니다.</li></ol><blockquote><p><strong>개발자 모드에서 더 나오는 것</strong>은 <a href="/RBQ/nightly/ko/manual/gui/developer-mode.html#emergency">개발자 모드</a>에 모아 두었습니다.</p></blockquote><h2 id="spectating" tabindex="-1">관전 <a class="header-anchor" href="#spectating" aria-label="Permalink to &quot;관전 {#spectating}&quot;">​</a></h2><p>로봇을 제어하는 기기는 한 번에 하나뿐입니다. 연결 중인데 다른 앱이나 컨트롤러가 소유권을 쥐고 있으면, 약 1초 뒤 이 기기는 관전으로 바뀝니다. 영상과 3D 화면은 그대로 나오지만 상단 바 아래의 조작은 모두 잠깁니다. 상단 바의 <code>E-STOP</code>, 시점 드롭다운, 상태 팝오버는 그대로 쓸 수 있습니다. 상단 바 바로 아래 가운데에 <code>관전</code> 버튼과 <code>다른 기기가 조종 중 · 눌러서 제어권 가져오기</code>가 표시됩니다.</p><p>허브·<code>설정</code>·로그 화면은 막지 않습니다. 허브에서는 <code>대시보드</code>·<code>정비</code> 타일이 잠기고 자동 기동 카드가 숨겨지며, <code>설정</code>에서는 로봇 탭만 잠기고 앱 탭은 그대로 쓸 수 있습니다. <code>관전</code> 버튼은 이 화면들에서도 상단 바 아래에 표시됩니다.</p><p>관전 중에는 시점 드롭다운에 <code>3D</code>와 <code>조종자 화면</code>만 나옵니다. 카메라는 조종 중인 기기가 고르므로 <code>조종자 화면</code>은 그 기기가 보는 카메라를 같이 보여 줍니다. 조종 중인 기기가 <code>3D</code>를 보고 있으면 <code>조종자 화면</code>도 3D로 바뀌고, 카메라로 돌아가면 다시 그 카메라가 나옵니다. 관전 중인 기기는 로봇 카메라를 켜거나 바꾸지 않습니다. 로봇 소리는 조종 중인 기기가 <code>로봇 소리 듣기</code>를 켜 둔 동안만 들립니다.</p><p>한 로봇을 동시에 관전할 수 있는 기기는 4대까지입니다(로봇 <code>Streamer.ini</code> 의 <code>[WebRTC]</code> <code>MAX_SPECTATORS</code>, 없으면 기본 4, <code>0</code> 이면 제한 없음. Streamer 가 켜질 때 읽음). 자리가 다 차면 빈자리가 날 때까지 영상이 나오지 않습니다. 이때 화면은 <code>3D</code>로 남고 <code>관전</code> 버튼에 <code>보는 기기가 많아 영상 대기 중 · 눌러서 제어권 가져오기</code>가 표시됩니다. 빈자리가 나면 영상은 저절로 나오고, 제어권은 자리와 상관없이 가져올 수 있습니다. 원격(WAN)으로 연결한 관전자에게는 영상 없이 3D 화면과 상태 표시만 나옵니다.</p><p><code>관전</code>을 누르면 <code>제어권을 가져올까요?</code>가 열립니다.</p><ul><li><code>제어권 가져오기</code> — 로봇에 소유권을 이 기기로 넘겨 달라고 요청합니다. 조종하던 기기는 관전으로 바뀝니다.</li><li><code>▶ 자동 기동</code> — <code>자동 기동을 실행할까요?</code> → <code>자동 기동</code> 확인 후 제어권을 가져오면서 자동 기동 시퀀스를 실행합니다.</li><li><code>계속 관전</code> — 메뉴를 닫습니다.</li></ul><p>제어 홈에서는 <code>시스템 종합 상태</code> 팝오버(상단 바의 상태 칩을 탭)에서도 소유권을 확인하고 가져올 수 있습니다. <code>소유권</code> 행에 이 기기가 소유자이면 <code>보유</code>, 아니면 <code>가져오기 ▸</code>가 표시됩니다.</p><p><img src="'+c+'" alt="시스템 종합 상태 팝오버의 소유권 행"></p><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/manual/safety/general-safety-warning-precautions.html">일반 안전 지침</a></li><li><a href="/RBQ/nightly/ko/manual/safety/emergency-stop-procedures.html">비상 정지 절차 (상세)</a></li></ul>',27)])])}const b=t(r,[["render",n]]);export{S as __pageData,b as default};
